import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel and function for cross entropy loss (FP32)
cross_entropy_source = """
#include <torch/extension.h>
#include <cmath>

__global__ void cross_entropy_kernel(const float* pred, const int* target, float* loss, int batch_size, int num_classes) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size) return;

    // Compute max of the row
    float max_val = -INFINITY;
    for (int j = 0; j < num_classes; ++j) {
        float val = pred[idx * num_classes + j];
        if (val > max_val) max_val = val;
    }

    // Sum of exp(val - max)
    float sum_exp = 0.0f;
    for (int j = 0; j < num_classes; ++j) {
        float val_shifted = pred[idx * num_classes + j] - max_val;
        float exp_val = expf(val_shifted);
        sum_exp += exp_val;
    }

    // Probability of the target class
    int t = target[idx];
    float prob_t = expf(pred[idx * num_classes + t] - max_val) / sum_exp;

    loss[idx] = -logf(prob_t);
}

torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets) {
    auto batch_size = predictions.size(0);
    auto num_classes = predictions.size(1);

    // Allocate output tensor of size batch_size
    torch::Tensor loss = torch::zeros(batch_size);
    float* out_ptr = loss.data_ptr<float>();

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    cross_entropy_kernel<<<num_blocks, block_size>>>(predictions.data_ptr<float()>, targets.data_ptr<int()>, out_ptr, batch_size, num_classes);

    return loss;
}
"""

# Compile the inline CUDA code for cross entropy
cross_entropy_cuda = load_inline(
    name="cross_entropy_cuda",
    cpp_sources=("torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets);"),
    cuda_sources=cross_entropy_source,
    functions=["cross_entropy_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.cross_entropy = cross_entropy_cuda

    def forward(self, predictions, targets):
        return self.cross_entropy(predictions, targets)
